mapper.select:
select t.test_id as testId, t.test_name as testName, t.tmpl_id as tmplId, t1.tmpl_name as tmplName, to_char(t.analysis_vdate,'YYYY-MM-DD') as analysisVDate, to_char(t.analysis_mdate,'YYYY-MM-DD') as analysisMDate, to_char(t.base_date,'YYYY-MM-DD') as baseDate, t.test_date as testDate, to_char(t.start_time,'yyyy-mm-dd HH24:mi:ss') as startTime, t.finished_time as finishedTime, t.exe_status as exeStatus, t.remark as remark, t4.tips_value as openMode, t3.scene_id as sceneId, t3.scene_name as sceneName, t.INSTITUTION_CODE as belongInstitutionCode from STT_STRESS_TEST t left join STT_STRESS_TMPL t1 on t1.tmpl_id=t.tmpl_id left join STT_STRESS_TIPS t2 on t.tmpl_id=t2.tmpl_id --left join STT_STRESS_SCENE t3 on t.test_id=t3.BUSI_ID and t3.stt_busi_type='04'--业务类型是04:压力测试 left join (select sttStrSce.BUSI_ID,sttStrSce.stt_busi_type,sttSce.scene_id,sttSce.scene_name from STT_STRESS_SCENE sttStrSce left join STT_SCENE sttSce on sttStrSce.scene_id = sttSce.scene_id)t3 on t.test_id=t3.BUSI_ID and t3.stt_busi_type='04'--业务类型是04:压力测试 left join stt_scene_tips t4 on t3.scene_id=t4.scene_id and t4.dict_code = 'OPENMODE'--适用产品（开放类型） where t2.dict_code='RISK_TYPE' and t2.tips_value='03'
and t4.tips_value = #{openMode}
and t.exe_status=#{exeStatus}
and to_char(t.base_date,'YYYY-MM-DD')>= substr(#{baseDate},0,10) and substr(#{baseDate},14,21) >= to_char(t.base_date,'YYYY-MM-DD')
and to_char(t.analysis_mdate,'YYYY-MM-DD')>= substr(#{analysisMDate},0,10) and substr(#{analysisMDate},14,21) >= to_char(t.analysis_mdate,'YYYY-MM-DD')
and to_char(t.start_time,'YYYY-MM-DD') >= substr(#{testDate},0,10) and substr(#{testDate},14,21) >= to_char(t.start_time,'YYYY-MM-DD')
and t.test_id in
#{item}
and t3.scene_id in
#{item}
order by t.start_time desc,t.exe_status desc
